# Keep all vocabulary in the hand-authored unit data consumed by the chapter
# adapter and source validator. Five groups of six make independent retrieval
# manageable while giving B1 thirty explicitly taught terms per unit.
for _unit, _extension in zip(UNITS, VOCAB_EXTENSION):
    _unit["vocab"].extend(_extension)


