    ["b1g01"], ["b1g02"], ["b1g03"], ["b1g04"], ["b1g05"], ["b1g06"],
    ["b1g07"], ["b1g08"], ["b1g09", "b1g10"], ["b1g11"], ["b1g12"], [],
