def _mcq(eid, title, kind, items):
    if kind == "listening":
        items = [dict(script=a, q=b, options=c, answer=d, explain=e)
                 for a, b, c, d, e in items]
    elif kind == "reading" and items and len(items[0]) == 5:
        items = [dict(text=a, q=b, options=c, answer=d, explain=e)
                 for a, b, c, d, e in items]
    else:
        items = [dict(q=a, options=b, answer=c, explain=d)
                 for a, b, c, d in items]
    digest = lambda value: hashlib.sha256(value.encode("utf-8")).digest()
    slot_order = sorted(range(4), key=lambda slot: digest(f"{eid}:slot:{slot}"))
    balanced = []
    for item_index, item in enumerate(items):
        options = list(item["options"])
        answer = item["answer"]
        if len(options) != 4 or len(set(options)) != 4 or not 0 <= answer < 4:
            raise ValueError(f"{eid}: each item needs four distinct options and a valid key")
        target = slot_order[item_index % 4]
        wrong = [i for i in range(4) if i != answer]
        wrong.sort(key=lambda choice: digest(f"{eid}:q{item_index}:choice:{choice}"))
        order = wrong[:]
        order.insert(target, answer)
        balanced.append({**item, "options": [options[i] for i in order], "answer": target})
    return MCQ(eid, title, kind,
               "Choose the answer supported by the language or text. Use the explanation to identify the evidence.",
               balanced)


def build_unit(index):
    u = UNITS[index - 1]
    n = index
    rows = [
        H(f"{n}.1 Words: language for {u['title'].split(':')[0].lower()}"),
        P(f"Begin with the situation. Learn {len(u['vocab'])} focus terms in five short sets. Listen for the purpose of each example and retrieve the meanings with your notes closed. The lesson also recycles A1 and A2 language; the focus list is not a claim that it contains every new word used in the stage."),
        *[
            WORDS(u["vocab"][start:start + 6], f"B1 unit {n}: focus vocabulary — set {start // 6 + 1}")
            for start in range(0, len(u["vocab"]), 6)
        ],
        H(f"{n}.2 Phrases: chunks for the situation"),
        P("Choose a phrase because it matches your meaning. Note one phrase, adapt its details to your own life, close your notes and say it in a different scene."),
        WORDS([(fr, "Link the words smoothly; stress the final syllable group.", en, "", "")
               for fr, en, _ in u["chunks"]], "Meaning, use and transfer"),
        H(f"{n}.3 Grammar: {u['grammar_title']}"),
        H3(u["grammar_title"]), P(u["grammar_body"]),
        TABLE(["Meaning", "Form", "Example (hear)", "English"], u["grammar_rows"], u["grammar_title"]),
        _mcq(f"{n}.3G", "Check the grammar choice", "reading", u["grammar_q"]),
        H(f"{n}.4 Dialogues: understand, respond and repair"),
        P("Listen for each speaker's goal and the detail that changes the exchange. First read for meaning; then cover the English and summarize each person's point."),
    ]
    for title, setting, lines in u["dialogues"]:
        rows.append(DIALOGUE(title, setting, lines))
    story = B1_STORIES.get(index)
    if story:
        rows += [
            H(f"{n}.5 Story: {story['title']}"),
            P(story["intro"]),
            STORY(story["title"], story["title_en"], story["sentences"], story["notes"]),
            _mcq(f"{n}.5R", "Read the story closely", "reading", story["questions"]),
        ]
    rows += [
        H(f"{n}.6 Listening: follow the point and useful details"),
        P("In learning mode, listen for the main point first. Then use the transcript and explanation to notice a useful phrase. For TCF-style questions in the final section, attempt the item once before checking the answer."),
        _mcq(f"{n}.6L", "Listen for meaning", "listening", u["listening"]),
        H(f"{n}.7 Reading: locate the evidence"),
        P("Read the question, identify the relevant sentence and distinguish what the text says from what you assume. Notices, dates and policies in this lesson are fictional practice material."),
        _mcq(f"{n}.7R", "Read and find the evidence", "reading", u["reading"]),
        H(f"{n}.8 Writing: plan, draft, check and revise"),
        WRITE(f"{n}.8W", f"TCF Task {u['write']['kind']} practice", u["write"]["prompt"],
              u["write"]["model"], u["write"]["checklist"]),
    ]
    for j, extra in enumerate(u.get("write_extra", []), 1):
        rows.append(WRITE(f"{n}.8W{j}", f"TCF Task {extra['kind']} practice",
                          extra["prompt"], extra["model"], extra["checklist"]))
    rows += [
        H(f"{n}.9 Speaking: interact, explain and transfer"),
        SPEAK(f"{n}.9S", "Goal-bound speaking practice", u["speak"]["prompt"],
              u["speak"]["model"], u["speak"]["tips"]),
    ]
    for j, extra in enumerate(u.get("speak_extra", []), 1):
        rows.append(SPEAK(f"{n}.9S{j}", extra["title"], extra["prompt"],
                          extra["model"], extra["tips"]))
    rows += [
        H(f"{n}.10 TCF corner and mastery checkpoint"),
        P("These are original practice items, not official TCF questions. Check the current France Éducation international candidate information before booking. A lesson checkpoint is evidence for review, not a predicted score."),
        _mcq(f"{n}.10L", "TCF-style listening: one play", "listening", u["listening"][:2]),
        _mcq(f"{n}.10R", "TCF-style reading", "reading", u["reading"][:2]),
        _mcq(f"{n}.10C", "Cumulative checkpoint", "reading", u["checkpoint"]),
        H(f"B1 Unit {n}: retrieve, then transfer"),
        LIST(
            "After one day, close your notes and retrieve five focus words and the grammar pattern.",
            "After several days, use the language in a new scene; bring back words that still need effort.",
            "Save one self-correction and one original example in your notes, then say the example without reading.",
            "Move on when you can complete the transfer task with notes closed; lesson completion is not a mastery score.",
        ),
    ]
    if index == 1:
        diagnostic = [
            H("1.0 B1 readiness check: record a baseline before Unit 1"),
            P("B1 assumes a completed A2 foundation. Before studying this unit, complete one short task in each skill with notes closed. Save the first attempt and one observation in your notes app. This is a learning baseline, not a placement decision or TCF score. If connecting past events, following clear short texts or managing a practical exchange is still difficult, review the corresponding A2 work before continuing."),
            _mcq("1.0L", "Baseline listening", "listening", B1_ENTRY_DIAGNOSTIC["listening"]),
            _mcq("1.0R", "Baseline reading", "reading", B1_ENTRY_DIAGNOSTIC["reading"]),
            WRITE("1.0W", "Baseline writing sample", B1_ENTRY_DIAGNOSTIC["write"]["prompt"],
                  B1_ENTRY_DIAGNOSTIC["write"]["model"], B1_ENTRY_DIAGNOSTIC["write"]["checklist"]),
            SPEAK("1.0S", "Baseline speaking sample", B1_ENTRY_DIAGNOSTIC["speak"]["prompt"],
                  B1_ENTRY_DIAGNOSTIC["speak"]["model"], B1_ENTRY_DIAGNOSTIC["speak"]["tips"]),
            *rows,
        ]
        rows = diagnostic
    ch = chapter(
        f"b1-u{n:02d}", f"B1 · Unit {n}", f"B1 · {u['title']}", badge=f"B1.{n}",
        can_do=u["can_do"], situation=u["situation"],
        canada=[
            "Scenarios are fictional adult-life contexts in Canada. They are language practice, not current legal, medical, financial, immigration or public-service instructions.",
            "Use clear, broadly intelligible French for production. Ask Marie to change details and roles so the learner practises meaning rather than a memorized script.",
            "For iPad split-screen study, record one pattern, one personal example and one correction; close notes before retrieval and return after a delay.",
        ],
        blocks=rows,
    )
    if story:
        ch["story_meta"] = {
            "id": story["id"], "minutes": 6, "summary": story["summary"],
            "keywords": story["keywords"],
        }
        ch["story_gloss"] = story["gloss"]
    return ch
